arguments.command:
cat << 'EOF' > /app/poster.html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>State of Developer Ecosystem 2024</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;600;700&family=Inter:wght@300;400;600;800&display=swap');

  :root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --accent-blue: #3b82f6;
    --accent-amber: #f59e0b;
    --accent-green: #10b981;
    --accent-purple: #8b5cf6;
  }

  body {
    margin: 0;
    padding: 0;
    background-color: var(--bg-color);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    width: 1200px;
    height: 1700px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .poster-container {
    padding: 60px 80px;
    display: flex;
    flex-direction: column;
    height: 100%;
    box-sizing: border-box;
    gap: 40px;
  }

  header {
    border-bottom: 2px solid #334155;
    padding-bottom: 30px;
  }

  h1 {
    font-family: 'Fira Code', monospace;
    font-size: 42px;
    margin: 0 0 15px 0;
    color: var(--text-main);
    text-transform: uppercase;
    letter-spacing: -1px;
  }

  .subtitle {
    font-size: 20px;
    color: var(--text-muted);
    margin: 0 0 25px 0;
    line-height: 1.5;
    max-width: 900px;
  }

  .global-stat {
    display: inline-block;
    background: rgba(59, 130, 246, 0.15);
    color: var(--accent-blue);
    border: 1px solid var(--accent-blue);
    padding: 8px 16px;
    border-radius: 4px;
    font-family: 'Fira Code', monospace;
    font-size: 16px;
    font-weight: 600;
  }

  .grid-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto 1fr;
    gap: 30px;
    flex-grow: 1;
  }

  /* Section 1: Trajectories (Takes full width) */
  .section-trajectories {
    grid-column: 1 / -1;
    background: var(--card-bg);
    border-radius: 12px;
    padding: 30px;
    border-top: 4px solid var(--accent-blue);
  }

  .section-title {
    font-family: 'Fira Code', monospace;
    font-size: 24px;
    color: var(--text-main);
    margin: 0 0 10px 0;
  }

  .section-desc {
    font-size: 16px;
    color: var(--text-muted);
    margin: 0 0 25px 0;
  }

  .charts-container {
    display: flex;
    gap: 20px;
    height: 300px;
  }

  .chart-box {
    flex: 1;
    height: 100%;
  }

  /* Section 2: Promise Index */
  .section-promise {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 30px;
    border-top: 4px solid var(--accent-amber);
    height: 400px;
  }

  /* Section 3: Databases & Cloud */
  .section-db-cloud {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 30px;
    border-top: 4px solid var(--accent-purple);
    height: 400px;
  }

  /* Section 4 & 5 */
  .section-platforms {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 30px;
    border-top: 4px solid var(--text-muted);
  }

  .section-ai {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 30px;
    border-top: 4px solid var(--accent-green);
    position: relative;
  }

  .ai-highlight {
    font-family: 'Fira Code', monospace;
    font-size: 64px;
    color: var(--accent-green);
    margin: 20px 0 10px 0;
    font-weight: 700;
  }

  .infographic-container {
    width: 100%;
    height: calc(100% - 60px);
  }

</style>
</head>
<body>

<div class="poster-container">
  <header>
    <h1>State of Developer Ecosystem 2024</h1>
    <div class="subtitle">A data-driven comparison of programming language trends, adoption trajectories, and the technologies reshaping the developer landscape in 2024.</div>
    <div class="global-stat">DATA: 23,262 DEVELOPERS WORLDWIDE</div>
  </header>

  <div class="grid-layout">

    <div class="section-trajectories">
      <h2 class="section-title">01. TOP PROGRAMMING LANGUAGES (2017–2024)</h2>
      <div class="section-desc">JavaScript plateaus, Python climbs steadily, and TypeScript surges explosively.</div>
      <div class="charts-container">
        <div class="chart-box" id="chart-js"></div>
        <div class="chart-box" id="chart-py"></div>
        <div class="chart-box" id="chart-ts"></div>
      </div>
    </div>

    <div class="section-promise">
      <h2 class="section-title">02. THE PROMISE INDEX</h2>
      <div class="section-desc">Top languages signaling where the ecosystem is heading.</div>
      <div class="infographic-container" id="info-promise"></div>
    </div>

    <div class="section-db-cloud">
      <h2 class="section-title">03. DATABASES & CLOUD</h2>
      <div class="section-desc">PostgreSQL's climb vs. MySQL's dominance, and Cloud leaders.</div>
      <div class="infographic-container" id="info-db"></div>
    </div>

    <div class="section-platforms">
      <h2 class="section-title">04. WHERE APPLICATIONS LIVE</h2>
      <div class="section-desc">Challenging the mobile-first assumption.</div>
      <div class="infographic-container" id="info-platforms"></div>
    </div>

    <div class="section-ai">
      <h2 class="section-title">05. AI INTEGRATION IN WORKFLOWS</h2>
      <div class="section-desc">AI steadily infiltrates production software.</div>
      <div class="ai-highlight">18%</div>
      <div style="font-size: 18px; color: #e2e8f0; margin-bottom: 20px;">of developers build integrations with AI</div>
      <div class="infographic-container" id="info-ai" style="height: 150px;"></div>
    </div>

  </div>
</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
  function renderInfo(id, syntax) {
    const container = document.getElementById(id);
    if (!container) return;
    const ig = new AntVInfographic.Infographic({
      container: container,
      width: '100%',
      height: '100%'
    });
    ig.render(syntax);
  }

  // Chart 1: JavaScript
  renderInfo('chart-js', `infographic chart-line-plain-text
data
  title JavaScript
  desc Plateau at 61%
  values
    - label 2017
      value 65
    - label 2019
      value 69
    - label 2021
      value 69
    - label 2023
      value 61
    - label 2024
      value 61
theme
  palette #94a3b8`);

  // Chart 2: Python
  renderInfo('chart-py', `infographic chart-line-plain-text
data
  title Python
  desc Steady climb to 57%
  values
    - label 2017
      value 32
    - label 2019
      value 49
    - label 2021
      value 52
    - label 2023
      value 54
    - label 2024
      value 57
theme
  palette #3b82f6`);

  // Chart 3: TypeScript
  renderInfo('chart-ts', `infographic chart-line-plain-text
data
  title TypeScript
  desc Explosive 12→37% growth
  values
    - label 2017
      value 12
    - label 2019
      value 25
    - label 2021
      value 29
    - label 2023
      value 34
    - label 2024
      value 37
theme
  palette #f59e0b`);

  // Promise Index
  renderInfo('info-promise', `infographic list-row-horizontal-icon-arrow
data
  title Top Rising Stars
  desc TypeScript and Rust lead the Promise Index
  lists
    - label TypeScript (199)
      desc #1 outlook, explosive adoption
      icon star fill
    - label Rust (198)
      desc #2 outlook, prized for performance
      icon flash
    - label Python (151)
      desc #3 outlook, dominant in AI/ML
      icon chart bar
    - label Go (129)
      desc #4 outlook, high concurrency
      icon server
theme
  palette #f59e0b #10b981 #3b82f6 #8b5cf6`);

  // Databases
  renderInfo('info-db', `infographic compare-binary-horizontal-simple-fold
data
  title Databases 2024
  compares
    - label PostgreSQL
      children
        - label Usage
          value 45
          icon arrow up bold
    - label MySQL
      children
        - label Usage
          value 52
          icon minus
theme
  palette #3b82f6 #94a3b8`);

  // Platforms
  renderInfo('info-platforms', `infographic compare-quadrant-quarter-simple-card
data
  title Execution Platforms
  compares
    - label Browser (58%)
    - label Server/Cloud (56%)
    - label Desktop (53%)
    - label Mobile (30%)
theme
  palette #3b82f6 #8b5cf6 #10b981 #f59e0b`);

  // AI Work
  renderInfo('info-ai', `infographic list-row-horizontal-icon-arrow
data
  title AI Domain Leaders
  desc Python dominates, C++ emerges
  lists
    - label Python (31%)
      desc Dominant in AI/ML
      icon star
    - label C++ (11%)
      desc Surprising systems player
      icon cpu
theme
  palette #10b981 #8b5cf6`);

</script>
</body>
</html>
EOF
